      "purpose": "Workflow-only script managing CSPRNG seed injection, projection generation, deterministic verification, and atomic cleanup",
      "content": "const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const { execSync } = require('child_process');

const REPO_ROOT = path.resolve(__dirname, '..');
const CATALOG_PATH = path.join(__dirname, 'catalog.json');
const SELECTOR_PATH = path.join(__dirname, 'selector.json');
const EVIDENCE_PATH = path.join(__dirname, 'evidence.json');
const STATE_PATH = path.join(__dirname, 'state.json');
const STATUS_PATH = path.join(__dirname, 'status.json');
const PROJECTIONS_DIR = path.join(__dirname, 'projections');

function loadJson(filePath) {
  return JSON.parse(fs.readFileSync(filePath, 'utf-8'));
}

function writeJson(filePath, data) {
  fs.writeFileSync(filePath, JSON.stringify(data, null, 2) + '\n');
}

function validateSelector(selector, catalog) {
  if (!selector || typeof selector !== 'object' || Array.isArray(selector)) {
    throw new Error('Selector must be a JSON object');
  }
  const allowedKeys = new Set(Object.keys(catalog));
  for (const [key, val] of Object.entries(selector)) {
    if (!allowedKeys.has(key)) {
      throw new Error(`Unrecognized document selector key: "${key}". Arbitrary paths rejected.`);
    }
    if (typeof val !== 'boolean') {
      throw new Error(`Selector value for "${key}" must be a boolean, received ${typeof val}`);
    }
  }
}

function projectNonJson(rawText, docId) {
  const lines = rawText.split('\n');
  const records = [];
  let currentTopic = null;
  let currentPara = [];
  let recordIndex = 0;

  function flushPara() {
    if (currentPara.length > 0) {
      records.push({
        index: recordIndex++,
        topic: currentTopic,
        text: currentPara.join('\n'),
        truth_seed: null
      });
      currentPara = [];
    }
  }

  for (const line of lines) {
    const trimmed = line.trim();
    if (trimmed.startsWith('#')) {
      flushPara();
      currentTopic = trimmed.replace(/^#+\s*/, '');
      records.push({
        index: recordIndex++,
        topic: currentTopic,
        text: line,
        truth_seed: null
      });
    } else if (trimmed === '') {
      flushPara();
    } else {
      currentPara.push(line);
    }
  }
  flushPara();

  if (records.length === 0) {
    records.push({ index: 0, topic: null, text: '', truth_seed: null });
  }

  const targetCount = Math.min(Math.max(3, Math.ceil(records.length / 4)), records.length);
  const step = records.length / targetCount;
  const seededIndices = new Set();
  for (let k = 0; k < targetCount; k++) {
    seededIndices.add(Math.min(Math.floor(k * step), records.length - 1));
  }
  seededIndices.add(0);
  seededIndices.add(records.length - 1);

  const expectedSeeds = [];
  for (let i = 0; i < records.length; i++) {
    if (seededIndices.has(i)) {
      const seed = crypto.randomBytes(16).toString('hex');
      records[i].truth_seed = seed;
      expectedSeeds.push(seed);
    }
  }

  return {
    projection: {
      document_id: docId,
      projection_type: 'non_json_records',
      total_records: records.length,
      records: records
    },
    seeds: expectedSeeds
  };
}

function projectJson(rawText, docId) {
  const parsed = JSON.parse(rawText);
  const cloned = JSON.parse(JSON.stringify(parsed));

  const targets = [];
  function collect(val, pathStr) {
    if (val && typeof val === 'object') {
      if (!Array.isArray(val)) {
        targets.push({ obj: val, path: pathStr });
      }
      for (const [k, v] of Object.entries(val)) {
        collect(v, Array.isArray(val) ? `${pathStr}[${k}]` : `${pathStr}.${k}`);
      }
    }
  }
  collect(cloned, '$');

  const expectedSeeds = [];
  if (targets.length === 0) {
    const seed = crypto.randomBytes(16).toString('hex');
    expectedSeeds.push(seed);
    return {
      projection: {
        document_id: docId,
        projection_type: 'json_preserve',
        truth_seed: seed,
        data: cloned
      },
      seeds: expectedSeeds
    };
  }

  const targetCount = Math.min(Math.max(3, Math.ceil(targets.length / 3)), targets.length);
  const step = targets.length / targetCount;
  const targetIndices = new Set();
  for (let k = 0; k < targetCount; k++) {
    targetIndices.add(Math.min(Math.floor(k * step), targets.length - 1));
  }
  targetIndices.add(0);
  targetIndices.add(targets.length - 1);

  for (let i = 0; i < targets.length; i++) {
    if (targetIndices.has(i)) {
      const seed = crypto.randomBytes(16).toString('hex');
      targets[i].obj._truth_seed = seed;
      expectedSeeds.push(seed);
    }
  }

  return {
    projection: {
      document_id: docId,
      projection_type: 'json_preserve',
      data: cloned
    },
    seeds: expectedSeeds
  };
}

function run() {
  const catalog = loadJson(CATALOG_PATH);
  const selector = loadJson(SELECTOR_PATH);
  const evidence = loadJson(EVIDENCE_PATH);
  const state = loadJson(STATE_PATH);

  const hasEvidence = Array.isArray(evidence.seeds) && evidence.seeds.length > 0;

  if (hasEvidence) {
    handleVerify(state, evidence, selector, catalog);
  } else {
    validateSelector(selector, catalog);
    const selectedDocs = Object.keys(selector).filter(k => selector[k] === true).sort();
    if (selectedDocs.length > 0) {
      handleGenerate(selectedDocs, catalog);
    } else {
      console.log('[truth-reader] No documents selected and no evidence submitted. Idle.');
    }
  }
}

function handleGenerate(selectedDocs, catalog) {
  if (!fs.existsSync(PROJECTIONS_DIR)) {
    fs.mkdirSync(PROJECTIONS_DIR, { recursive: true });
  }

  const existingFiles = fs.readdirSync(PROJECTIONS_DIR);
  for (const f of existingFiles) {
    if (f !== '.gitkeep') {
      fs.unlinkSync(path.join(PROJECTIONS_DIR, f));
    }
  }

  const allExpectedSeeds = [];

  for (const docId of selectedDocs) {
    const entry = catalog[docId];
    const sourceFullPath = path.join(REPO_ROOT, entry.source);
    if (!fs.existsSync(sourceFullPath)) {
      throw new Error(`Authoritative source file missing: ${entry.source}`);
    }
    const rawText = fs.readFileSync(sourceFullPath, 'utf-8');

    let result;
    if (entry.format === 'json') {
      result = projectJson(rawText, docId);
    } else {
      result = projectNonJson(rawText, docId);
    }

    const projectionFullPath = path.join(REPO_ROOT, entry.projection);
    writeJson(projectionFullPath, result.projection);
    for (const s of result.seeds) {
      allExpectedSeeds.push(s);
    }
  }

  const expectedHashes = allExpectedSeeds.map(s => crypto.createHash('sha256').update(s).digest('hex'));
  writeJson(STATE_PATH, {
    active_selection: selectedDocs,
    expected_hashes: expectedHashes,
    seed_count: allExpectedSeeds.length,
    created_at: new Date().toISOString()
  });

  writeJson(STATUS_PATH, {
    status: 'CHALLENGE_ISSUED',
    message: `Generated projections for: ${selectedDocs.join(', ')}`,
    seed_count: allExpectedSeeds.length,
    timestamp: new Date().toISOString()
  });

  execSync('git config user.name "github-actions[bot]"', { stdio: 'inherit' });
  execSync('git config user.email "github-actions[bot]@users.noreply.github.com"', { stdio: 'inherit' });
  execSync('git add truth_reader/projections truth_reader/state.json truth_reader/status.json', { stdio: 'inherit' });
  execSync('git commit -m "[skip ci] Issue truth reader projections"', { stdio: 'inherit' });
  execSync('git push origin HEAD', { stdio: 'inherit' });

  console.log(`[truth-reader] Successfully issued challenge for [${selectedDocs.join(', ')}] with ${allExpectedSeeds.length} seeds.`);
}

function handleVerify(state, evidence, selector, catalog) {
  if (!state || !Array.isArray(state.expected_hashes) || state.expected_hashes.length === 0) {
    console.error('[truth-reader] FAIL: No active challenge state found to verify against.');
    process.exit(1);
  }

  if (evidence.seeds.length !== state.expected_hashes.length) {
    console.error(`[truth-reader] FAIL: Evidence count (${evidence.seeds.length}) does not match expected count (${state.expected_hashes.length}).`);
    process.exit(1);
  }

  for (let i = 0; i < state.expected_hashes.length; i++) {
    const submitted = String(evidence.seeds[i]);
    const hash = crypto.createHash('sha256').update(submitted).digest('hex');
    if (hash !== state.expected_hashes[i]) {
      console.error(`[truth-reader] FAIL: Truth seed mismatch at index ${i}.`);
      process.exit(1);
    }
  }

  for (const k of Object.keys(selector)) {
    selector[k] = false;
  }
  writeJson(SELECTOR_PATH, selector);

  writeJson(EVIDENCE_PATH, { seeds: [] });

  if (fs.existsSync(PROJECTIONS_DIR)) {
    const files = fs.readdirSync(PROJECTIONS_DIR);
    for (const f of files) {
      if (f !== '.gitkeep') {
        fs.unlinkSync(path.join(PROJECTIONS_DIR, f));
      }
    }
  }

  const validatedCount = state.expected_hashes.length;
  writeJson(STATE_PATH, {
    active_selection: null,
    expected_hashes: [],
    seed_count: 0
  });

  writeJson(STATUS_PATH, {
    status: 'PASS',
    message: 'Verification successful. All truth seeds validated in exact order.',
    validated_seeds: validatedCount,
    timestamp: new Date().toISOString()
  });

  execSync('git config user.name "github-actions[bot]"', { stdio: 'inherit' });
  execSync('git config user.email "github-actions[bot]@users.noreply.github.com"', { stdio: 'inherit' });
  execSync('git add truth_reader/', { stdio: 'inherit' });
  execSync('git commit -m "[skip ci] Reset truth reader challenge (PASS)"', { stdio: 'inherit' });
  execSync('git push origin HEAD', { stdio: 'inherit' });

  console.log(`[truth-reader] PASS: Successfully verified ${validatedCount} seeds and performed atomic cleanup.`);
}

run();"
    },
    {
      "path": ".github/workflows/truth-reader.yml",
      "purpose": "GitHub Actions workflow orchestrating projection generation, verification, and loop prevention",
      "content": "name: Truth Reader Challenge

on:
  push:
    paths:
      - 'truth_reader/selector.json'
      - 'truth_reader/evidence.json'

permissions:
  contents: write

jobs:
  truth-reader:
    if: github.actor != 'github-actions[bot]' && !contains(github.event.head_commit.message, '[skip ci]')
    runs-on: ubuntu-latest
    steps:
      - name: Checkout repository
        uses: actions/checkout@v4
        with:
          token: ${{ secrets.GITHUB_TOKEN }}
          fetch-depth: 0

      - name: Setup Node.js
        uses: actions/setup-node@v4
        with:
          node-version: '20'

      - name: Run Truth Reader Engine
        run: node truth_reader/truth_reader.js
        env:
          GITHUB_TOKEN: ${{ secrets.GITHUB_TOKEN }}"
    }
  ],
  "design_checks": {
    "authoritative_docs_immutable": true,
    "enumerated_doc_selector": true,
    "projection_from_current_source": true,
    "all_projections_are_json": true,
    "non_json_full_content_preserved": true,
    "distributed_seed_coverage": true,
    "workflow_only_seed_authority": true,
    "exact_complete_seed_match": true,
    "fail_is_noop": true,
    "pass_atomic_cleanup": true,
    "recursive_workflow_loop_prevented": true
  },
  "unresolved_requirements": []
}
